// __mocks__/priceService.js
export const price = (sku) => {
  const canned = { 'A-1': 9.99 };
  if (!(sku in canned)) throw new Error(`no canned price for ${sku}`);
  return Promise.resolve(canned[sku]);
};

const server = setupServer(
  http.get('/price/:sku', ({ params }) =>
    HttpResponse.json({ price: params.sku === 'A-1' ? 9.99 : 0 }))
);
beforeAll(() => server.listen());
afterEach(() => server.resetHandlers());
afterAll(() => server.close());
